export type Role = 'student' | 'editor' | 'admin' | 'superadmin'
/** Admin rights: admins and the super admin (app owner, whom other admins cannot change). */
export const isAdminRole = (r?: Role) => r === 'admin' || r === 'superadmin'
export const ROLE_ICON: Record<Role, string> = { student: '🙂', editor: '✏️', admin: '👑', superadmin: '⭐' }
export type Dir = 'en' | 'cz'
export type Grade = 'knew' | 'partial' | 'unknown'

export interface Profile { id: string; class_id: string; nickname: string; role: Role; created_at: string }
/** name is generated by the database: "6. D". school_year 2026 means 2026/2027. */
export interface ClassInfo { id: string; name: string; grade: number; letter: string; school_year: number; code: string }
export const CLASS_COLS = 'id, name, grade, letter, school_year, code'
export const schoolYear = (y: number) => `${y}/${y + 1}`
export const classLabel = (c: ClassInfo) => `${c.name} ${schoolYear(c.school_year)}`
/** School year that is running now: from September on it is this year's, before that last year's. */
export const currentSchoolYear = (d = new Date()) => (d.getMonth() >= 8 ? d.getFullYear() : d.getFullYear() - 1)
export interface Textbook { id: string; title: string; position: number }
export interface Lesson { id: string; textbook_id: string; title: string; position: number }
export interface Card {
  id: string; lesson_id: string; en: string; cz: string; note: string
  status: 'pending' | 'approved'; created_by: string | null; created_at: string
}
export interface Progress { user_id: string; card_id: string; dir: Dir; level: number; seen: number; last_seen: string | null; learned_at: string | null }
export interface Answer { user_id: string; card_id: string; dir: Dir; grade: Grade; answered_at: string }

export const LEARNED = 3
export const pkey = (cardId: string, dir: Dir) => `${dir}|${cardId}`
export interface BugReport {
  id: string; user_id: string; message: string; page: string; device: string; errors: string
  status: 'new' | 'done'; created_at: string; resolved_at: string | null
}
